/**
 * EVALUADOR DE ACTIVOS (BRANCHING) - CommunityLab (Nodo 7)
 * Aplica las reglas del contrato para activar o desactivar las ramas de generación.
 */

const input = $input.first().json;
const interacciones = input.interacciones_analizadas || [];
const opciones = input.opciones || {};

// Arreglos para agrupar evidencias clasificadas
const testimoniosLogros = [];
const preguntasDudas = [];

// 1. Evaluar interacciones analizadas
interacciones.forEach(item => {
  const analisis = item.analisis || {};
  const tipoInsight = (analisis.tipo_insight || "").toLowerCase();
  const sentimiento = (analisis.sentimiento || "").toLowerCase();

  // Regla: Testimonio o Logro con Sentimiento Positivo
  const esTestimonio = tipoInsight.includes("testimonio") || tipoInsight.includes("logro");
  const esPositivo = sentimiento.includes("positi");

  if (esTestimonio && esPositivo) {
    testimoniosLogros.push(item);
  }

  // Regla: Pregunta Técnica o Duda
  const esPregunta = tipoInsight.includes("pregunta") || tipoInsight.includes("duda") || tipoInsight.includes("tecnica");
  if (esPregunta) {
    preguntasDudas.push(item);
  }
});

// 2. Determinar activos a generar
let activosAProcesar = [];

// Si vienen opciones explicitas (Override)
if (Array.isArray(opciones.generar_activos) && opciones.generar_activos.length > 0) {
  activosAProcesar = opciones.generar_activos.map(a => a.toUpperCase());
} else {
  // Aplicar reglas automaticas del contrato
  if (testimoniosLogros.length > 0) {
    activosAProcesar.push("LINKEDIN");
    activosAProcesar.push("NEWSLETTER");
  }
  if (preguntasDudas.length > 0) {
    activosAProcesar.push("FAQ");
  }
}

// 3. Devolver contexto enriquecido con banderas de decisión
return [{
  json: {
    origen_comunidad: input.origen_comunidad,
    periodo_referencia: input.periodo_referencia,
    resumen_comunidad: input.resumen_comunidad,
    decisiones_branching: {
      generar_linkedin: activosAProcesar.includes("LINKEDIN"),
      generar_newsletter: activosAProcesar.includes("NEWSLETTER"),
      generar_faq: activosAProcesar.includes("FAQ"),
      activos_solicitados: activosAProcesar
    },
    evidencias: {
      testimonios_logros: testimoniosLogros,
      preguntas_dudas: preguntasDudas
    }
  }
}];

