/**
 * CONSOLIDADOR DE ANÁLISIS DE LOTE - CommunityLab (Nodo 6)
 * Reagrupa los resultados individuales del LLM y calcula métricas globales.
 */

const items = $input.all();
if (items.length === 0) return [];

const interaccionesAnalizadas = [];
let positivos = 0;
let neutros = 0;
let negativos = 0;
const conjuntoTemas = new Set();

items.forEach((item, index) => {
  const json = item.json;

  // Extraer el análisis individual (o fallback si el ítem falló)
  const analisis = json.analisis || {
    sentimiento: "Neutro",
    relevancia: "Media",
    tipo_insight: "otro",
    temas: ["Sin categorizar"],
    resumen: "No se pudo obtener el análisis del LLM.",
    evidencia_clave: json.texto || ""
  };

  // Contabilizar sentimientos
  const sentimiento = (analisis.sentimiento || "").toLowerCase();
  if (sentimiento.includes("positi")) positivos++;
  else if (sentimiento.includes("nega")) negativos++;
  else neutros++;

  // Recolectar temas
  if (Array.isArray(analisis.temas)) {
    analisis.temas.forEach(t => conjuntoTemas.add(t));
  }

  // Mapear al objeto unificado de interacción analizada
  interaccionesAnalizadas.push({
    id_temporal: json.id_temporal || `INT-${index + 1}`,
    autor: json.autor || "Anónimo",
    canal: json.canal || "#general",
    tipo_declarado: json.tipo || "desconocido",
    texto_original: json.texto || json.texto_original || "",
    analisis: analisis
  });
});

// Determinar el sentimiento predominante del lote
let sentimientoPredominante = "Neutro";
if (positivos >= neutros && positivos >= negativos) {
  sentimientoPredominante = "Positivo";
} else if (negativos > positivos && negativos >= neutros) {
  sentimientoPredominante = "Negativo";
}

// Datos de contexto raíz (recuperados de la iteración)
const primerItem = items[0].json;
const origenComunidad = primerItem.origen_comunidad || "Comunidad_General";
const periodoReferencia = primerItem.periodo_referencia || "Semana_Actual";
const opciones = primerItem.opciones || { generar_activos: ["LINKEDIN", "NEWSLETTER", "FAQ"] };

return [{
  json: {
    origen_comunidad: origenComunidad,
    periodo_referencia: periodoReferencia,
    opciones: opciones,
    resumen_comunidad: {
      total_interacciones_procesadas: interaccionesAnalizadas.length,
      sentimiento_predominante: sentimientoPredominante,
      distribucion_sentimientos: {
        positivos: positivos,
        neutros: neutros,
        negativos: negativos
      },
      temas_principales: Array.from(conjuntoTemas)
    },
    interacciones_analizadas: interaccionesAnalizadas
  }
}];

/**
 * Continuar cuando no hay activos a generar (o para forzar construcción).
 * Emite un item que permite al Merge/Construir cerrar el flujo.
 */
const input = $input.first().json;
const d = input.decisiones_branching || {};
const alguno = d.generar_linkedin || d.generar_newsletter || d.generar_faq;

if (alguno) {
  // Hay ramas activas: no emitir aquí (las cubren los generadores)
  return [];
}

// Ningún activo: emitir marcador para que Construir genere respuesta vacía de activos
return [{
  json: {
    status: "no_requerido",
    rama: "ninguno",
    ...input
  }
}];

// Script rápido para el output final si se añade un nodo Code tras OCI
const entrada = $input.first().json;

entrada.decisiones_branching.generar_linkedin = false;
entrada.decisiones_branching.generar_newsletter = false;
entrada.decisiones_branching.generar_faq = false;

return [{ json: entrada }];

/**
 * NODO MOCK DE PRUEBA - Simula la salida del Analista LLM (Nodo 5)
 */

const items = $input.all();

// Mapeamos los ítems de entrada devolviendo análisis ficticios pero válidos
return items.map((item, index) => {
  const json = item.json;

  // Lista de temas mock para simular la salida de la IA
  const temasEjemplo = [
    ["Logros y empleos", "Oracle Cloud (OCI)"],
    ["Dudas n8n", "LangGraph"],
    ["Despliegue OCI", "Always Free"],
    ["Dudas técnicas", "OCI Storage"],
    ["Feedback Cursos", "Prompt Engineering"]
  ];

  const tiposEjemplo = ["testimonio", "pregunta_tecnica", "testimonio", "pregunta_tecnica", "feedback"];

  return {
    json: {
      ...json,
      status: "exito",
      analisis: {
        sentimiento: index % 2 === 0 ? "Positivo" : "Neutro",
        relevancia: "Alta",
        tipo_insight: tiposEjemplo[index % tiposEjemplo.length],
        temas: temasEjemplo[index % temasEjemplo.length],
        resumen: `Resumen de prueba para la interacción ${index + 1}: ${json.texto ? json.texto.substring(0, 40) : 'Sin texto'}...`,
        evidencia_clave: json.texto || "Evidencia de prueba"
      }
    }
  };
});

const item = $input.first().json;

// 1. Detectar si los datos vienen encapsulados por un Webhook (.body) o si son un JSON directo
const input = item.body ? item.body : item;
const errores = [];

// 2. Validar origen_comunidad
if (!input.origen_comunidad || typeof input.origen_comunidad !== 'string' || input.origen_comunidad.trim() === '') {
  errores.push("El campo 'origen_comunidad' es obligatorio y no puede estar vacío.");
}

// 3. Validar periodo_referencia
if (!input.periodo_referencia || typeof input.periodo_referencia !== 'string' || input.periodo_referencia.trim() === '') {
  errores.push("El campo 'periodo_referencia' es obligatorio y no puede estar vacío.");
}

// 4. Validar array de interacciones
if (!Array.isArray(input.interacciones) || input.interacciones.length === 0) {
  errores.push("El campo 'interacciones' debe ser un array con al menos 1 elemento.");
} else {
  input.interacciones.forEach((item, index) => {
    if (!item || typeof item !== 'object' || !item.texto || typeof item.texto !== 'string' || item.texto.trim() === '') {
      errores.push(`La interacción en el índice ${index} no contiene un campo 'texto' válido o está vacía.`);
    }
  });
}

const esValido = errores.length === 0;

return [{
  json: {
    es_valido: esValido,
    errores: errores,
    payload_original: input
  }
}];

/**
 * NORMALIZADOR DE ENTRADAS - CommunityLab (Nodo 3)
 * Convierte cualquier payload entrante validado a la estructura interna uniforme.
 */

const items = $input.all();
if (items.length === 0) return [];

const primerElemento = items[0].json;

// 1. Extraer la raíz según la fuente (Webhook o Payload directo/Normal)
let rootData = primerElemento;
if (primerElemento.payload_original) {
  // Si viene de la salida estructurada del Nodo 2 (Validación)
  rootData = primerElemento.payload_original;
} else if (primerElemento.body && primerElemento.body.interacciones) {
  // Si viene directo del Webhook
  rootData = primerElemento.body;
}

// 2. Extraer metadatos de nivel raíz
const origenComunidad = rootData.origen_comunidad || rootData.Origen_Comunidad || "Comunidad_General";
const periodoReferencia = rootData.periodo_referencia || rootData.Periodo_Referencia || "Periodo_Actual";
const opciones = rootData.opciones || {
  idioma: "es",
  tono: "inspirador"
};
// Importante: NO rellenar generar_activos por defecto.
// Si el request no trae opciones.generar_activos, el Evaluador
// aplica las reglas automáticas de branching (testimonio/duda).
if (rootData.opciones && Array.isArray(rootData.opciones.generar_activos)) {
  opciones.generar_activos = rootData.opciones.generar_activos;
}

// 3. Normalizar la lista de interacciones
let interaccionesRaw = [];

if (Array.isArray(rootData.interacciones)) {
  interaccionesRaw = rootData.interacciones;
} else if (Array.isArray(items) && items.length > 0 && items[0].json.Texto) {
  // Caso de respaldo si viniese como filas individuales de CSV/Sheets
  interaccionesRaw = items.map(item => item.json);
}

const interaccionesNormalizadas = interaccionesRaw.map((item, index) => {
  return {
    id_temporal: `INT-${index + 1}`,
    autor: (item.autor || item.Autor || "Anónimo").trim(),
    canal: (item.canal || item.Canal || "#general").trim(),
    tipo: (item.tipo || item.Tipo || "desconocido").toLowerCase().trim(),
    texto: (item.texto || item.Texto || "").trim(),
    identificador_origen: item.identificador_origen || item.ID_Interaccion || null,
    momento_origen: item.momento_origen || item.Fecha_Registro || null
  };
});

// 4. Retornar el objeto normalizado que viajará por el resto del workflow
return [{
  json: {
    origen_comunidad: origenComunidad,
    periodo_referencia: periodoReferencia,
    total_interacciones: interaccionesNormalizadas.length,
    opciones: opciones,
    interacciones: interaccionesNormalizadas
  }
}];

