/**
 * CONSTRUCTOR DE PAQUETE FINAL - CommunityLab (Nodo 9)
 * Compatible con Merge en modo Append o passthrough.
 * Procesa todos los ítems recibidos sin importar si provienen de 1, 2 o 3 generadores.
 */

const contextoBase = $('Consolidar Analisis Lote').first()?.json || {};
const itemsEntrada = $input.all();

// Estructura por defecto para activos no requeridos o no generados
let postLinkedin = { status: "no_requerido" };
let destaqueNewsletter = { status: "no_requerido" };
let sugerenciaFAQ = { status: "no_requerido" };

// Recorrer los elementos entregados por el nodo Merge
for (const item of itemsEntrada) {
  let datos = item.json;

  // Si el generador devolvió el contenido dentro del string 'text', parsearlo
  if (datos.text && typeof datos.text === 'string') {
    try {
      datos = JSON.parse(datos.text);
    } catch (e) {
      datos = { status: "error_parseo", raw: datos.text };
    }
  }

  // Identificar el tipo de activo según su contenido
  if (datos.titulo || datos.copy || datos.canal_recomendado) {
    postLinkedin = datos;
  } else if (datos.seccion || datos.titular) {
    destaqueNewsletter = datos;
  } else if (datos.tema || datos.contenido_sugerido || datos.origen) {
    sugerenciaFAQ = datos;
  }
}

// Construir metadatos y ruta para OCI
const fechaISO = new Date().toISOString();
const timestamp = fechaISO.replace(/[:.-]/g, '');
const periodoRef = (contextoBase.periodo_referencia || 'semana_actual').toLowerCase().replace(/\s+/g, '_');
const rutaObjetoOCI = `activos/${periodoRef}/paquete-${timestamp}.json`;

const paqueteFinal = {
  status: "exito",
  origen_comunidad: contextoBase.origen_comunidad || "Comunidad_General",
  periodo_referencia: contextoBase.periodo_referencia || "Semana_Actual",
  resumen_comunidad: contextoBase.resumen_comunidad || {},
  activos_distribucion_generados: {
    post_linkedin: postLinkedin,
    destaque_newsletter_semanal: destaqueNewsletter,
    sugerencia_contenido_faq: sugerenciaFAQ
  },
  almacenamiento_oci: {
    bucket: "communitylab-activos-marketing",
    ruta_objeto: rutaObjetoOCI,
    status: "pendiente"
  },
  meta: {
    procesado_en: fechaISO,
    modo: "solo_oci",
    workflow_execution_id: $execution.id || "ejecucion_local"
  }
};

return [{ json: paqueteFinal }];

// Script rápido para el output final si se añade un nodo Code tras OCI
const entrada = $input.first().json;

entrada.almacenamiento_oci.status = "guardado_con_exito";

return [{ json: entrada }];

/**
 * NODO MOCK OCI UPLOAD - CommunityLab (Nodo 10)
 * Simula la subida exitosa a OCI Object Storage sin requerir credenciales S3/OCI real.
 */

// 1. Recibir el paquete estructurado desde el Nodo 9 (Construir Response + Paquete)
const entrada = $input.first().json;

// 2. Simular los datos devueltos por la API REST / S3 de OCI
const regionOCI = "us-ashburn-1";
const namespaceOCI = "ax1234567mock";
const bucketName = entrada.almacenamiento_oci?.bucket || "communitylab-activos-marketing";
const rutaObjeto = entrada.almacenamiento_oci?.ruta_objeto || "activos/semana_actual/paquete-mock.json";

// Generar una URL pública/firmada simulada de OCI Object Storage
const urlObjetoSimulada = `https://${objectStorageDomain(namespaceOCI, regionOCI)}/${bucketName}/${rutaObjeto}`;

function objectStorageDomain(ns, region) {
  return `${ns}.objectstorage.${region}.oraclecloud.com`;
}

// 3. Actualizar el estado de persistencia para cumplir con el contrato
entrada.almacenamiento_oci = {
  ...entrada.almacenamiento_oci,
  status: "guardado_con_exito",
  detalles_mock: {
    mensaje: "Respuesta simulada de OCI Object Storage (Modo Pruebas)",
    url_simulada: urlObjetoSimulada,
    etag: `mock-etag-${Date.now()}`,
    tamano_bytes: JSON.stringify(entrada).length
  }
};

return [{ json: entrada }];
